<script setup lang="ts">import{ref}from"vue";import{exportsApi}from"../../api/exports";const props=defineProps<{type:"analysis"|"conversation";sourceId:number}>();const busy=ref(false);async function run(){busy.value=true;try{const record=await exportsApi.create(props.type,props.sourceId,"研究记录","");window.location.assign(exportsApi.downloadUrl(record.id))}finally{busy.value=false}}</script><template><button :disabled="busy" @click="run">{{busy?'导出中…':'导出 Markdown'}}</button></template>
